  var map = { "\u91d1":{num:"4\u30019",color:"\u767d\u8272\u3001\u91d1\u8272",dir:"\u897f\u65b9"}, "\u6728":{num:"3\u30018",color:"\u7eff\u8272\u3001\u9752\u8272",dir:"\u4e1c\u65b9"}, "\u6c34":{num:"1\u30016",color:"\u9ed1\u8272\u3001\u84dd\u8272",dir:"\u5317\u65b9"}, "\u706b":{num:"2\u30017",color:"\u7ea2\u8272\u3001\u7d2b\u8272",dir:"\u5357\u65b9"}, "\u571f":{num:"5\u300110",color:"\u9ec4\u8272\u3001\u68d5\u8272",dir:"\u4e2d\u592e"} };
