function getAnnualFortune(params){
  var now = new Date();
  var y = now.getFullYear();
  var gz = (typeof yGz === "function") ? yGz(y) : null;
  var gan = gz && gz.s !== undefined ? gz.s : "";
  var zhi = gz && gz.b !== undefined ? gz.b : "";
  var el = "";
  var sx = "";
  try{ if(typeof ELEM !== "undefined" && ELEM[gan]) el = ELEM[gan]; }catch(err){}
  try{ if(typeof SX !== "undefined" && SX[zhi]) sx = SX[zhi]; }catch(err){}
  var desired = getDesiredElements(params);
  var score = desired.indexOf(el) >= 0 ? 5 : (el ? 2 : 3);
  var text = "\u4eca\u5e74\u662f" + y + "\u5e74\uff0c\u6d41\u5e74\u4e94\u884c\u5c5e" + (el || "\u7efc\u5408") + (sx ? "\uff0c\u751f\u8096\u4e3a" + sx : "") + "\u3002";
  if(score >= 5) text += "\u6d41\u5e74\u4e94\u884c\u4e0e\u516b\u5b57\u6240\u9700\u76f8\u5408\uff0c\u9002\u5408\u628a\u63e1\u673a\u4f1a\u3001\u63a8\u8fdb\u4e8b\u4e1a\u4e0e\u5bb6\u5ead\u8ba1\u5212\u3002";
  else if(score >= 3) text += "\u6d41\u5e74\u8fd0\u52bf\u603b\u4f53\u5e73\u7a33\uff0c\u5b9c\u7a33\u4e2d\u6c42\u8fdb\uff0c\u6ce8\u91cd\u5065\u5eb7\u548c\u4eba\u9645\u6c9f\u901a\u3002";
  else text += "\u6d41\u5e74\u4e94\u884c\u4e0e\u516b\u5b57\u6240\u9700\u6709\u6240\u504f\u5dee\uff0c\u5efa\u8bae\u8865\u8db3" + desired.join("\u3001") + "\uff0c\u91cd\u5927\u51b3\u7b56\u5b9c\u591a\u6838\u5bf9\u3002";
  return text;
}


