function getDreamCategory(text){
  var t = text || "";
  if(/[\u8d22\u94b1\u91d1\u9c7c\u6c34\u5bcc\u8d22]/.test(t)) return "\u8d22\u8fd0\u53c2\u8003";
  if(/[\u7231\u5a5a\u604b\u60c5\u82b1\u73ab\u7470\u9e33\u9e2f]/.test(t)) return "\u611f\u60c5\u53c2\u8003";
  if(/[\u5de5\u4f5c\u4e8b\u4e1a\u5347\u804c\u5b98\u9f99\u9a6c\u98de]/.test(t)) return "\u4e8b\u4e1a\u53c2\u8003";
  if(/[\u75c5\u4f24\u8840\u6b7b\u9b3c\u75db]/.test(t)) return "\u5065\u5eb7\u8b66\u793a";
  return "\u7efc\u5408\u53c2\u8003";
}

function searchDreamLegacy(){
  var input = document.getElementById("dreamSearch");
  if(!input) return;
  var q = input.value.trim();
  var box = document.getElementById("dreamResults");
  if(!box) return;
  if(!q){ box.innerHTML = '<p style="color:#999;font-size:0.85rem">\u8bf7\u8f93\u5165\u68a6\u5883\u5173\u952e\u8bcd</p>'; return; }
  var results = DREAM_DATA.filter(function(item){
    return item.t.indexOf(q) >= 0 || item.keyword.indexOf(q) >= 0 || item.d.indexOf(q) >= 0;
  });
  if(results.length === 0){
    var qchars = q.split("");
    var scored = [];
    for(var si = 0; si < DREAM_DATA.length; si++){
      var item = DREAM_DATA[si];
      var hayT = item.t || "";
      var hayK = item.keyword || "";
      var hayD = item.d || "";
      var score = 0;
      if(hayT.indexOf(q) >= 0) score += 100;
      if(hayK.indexOf(q) >= 0) score += 80;
      if(hayD.indexOf(q) >= 0) score += 40;
      for(var ci = 0; ci < qchars.length; ci++){
        var ch = qchars[ci];
        if(hayT.indexOf(ch) >= 0 || hayK.indexOf(ch) >= 0) score += 15;
        else if(hayD.indexOf(ch) >= 0) score += 5;
      }
      if(qchars.length === 1 && (hayT.indexOf(q) >= 0 || hayK.indexOf(q) >= 0)) score += 30;
      if(score >= (qchars.length > 1 ? 20 : 40)) scored.push({item:item, score:score});
    }
    scored.sort(function(a,b){ return b.score - a.score; });
    var source = scored.slice(0, 50);
    var h = '<div style="padding:1rem;background:#FFF8EC;border:1px solid #EAD9BE;border-radius:12px;margin-bottom:0.8rem">';
    if(source.length){
      h += '<p style="font-size:0.9rem;color:#6B4B1F;margin-bottom:0.5rem">\u672a\u627e\u5230\u5b8c\u6574\u5339\u914d\uff0c\u4e3a\u4f60\u7b5b\u9009\u4e86 ' + source.length + ' \u6761\u76f8\u5173\u5ea6\u8f83\u9ad8\u7684\u89e3\u68a6\u8bcd\u6761\uff1a</p>';
    }else{
      source = DREAM_DATA.slice(0, 8).map(function(item){ return {item:item, score:0}; });
      h += '<p style="font-size:0.9rem;color:#6B4B1F;margin-bottom:0.5rem">\u672a\u627e\u5230\u8db3\u591f\u76f8\u5173\u7684\u8bcd\u6761\uff0c\u4ee5\u4e0b\u4e3a\u70ed\u95e8\u89e3\u68a6\u4f9b\u4f60\u53c2\u8003\uff1a</p>';
    }
    source.slice(0, 50).forEach(function(row, index){
      var item = row.item;
      h += '<div style="margin-bottom:0.6rem;padding:0.7rem;background:#fff;border:1px solid #F0DFC0;border-radius:8px"><b style="color:#AF2020">' + (index+1) + '. ' + item.t + '</b><p style="font-size:0.82rem;color:#555;margin-top:0.3rem">' + item.d + '</p></div>';
    });
    h += '</div>';
    box.innerHTML = h; return;
  }
  var show = results.slice(0, 50);
  var h = '<div style="padding:1rem;background:linear-gradient(135deg,#FFF8EC,#FDEBD2);border:1.5px solid #D4A030;border-radius:12px;margin-bottom:0.8rem">';
  h += '<div style="display:flex;align-items:center;justify-content:space-between;gap:0.5rem;flex-wrap:wrap"><b style="font-size:1.05rem;color:#AF2020">\u68a6\u5883\u62a5\u544a</b><span style="font-size:0.75rem;color:#8A5A2B">\u5171 ' + results.length + ' \u6761\u76f8\u5173\u8bcd\u6761</span></div>';
  h += '<div style="font-size:0.72rem;color:#999;margin:0.4rem 0 0.7rem">\u62a5\u544a\u7f16\u53f7\uff1aJS-' + Date.now().toString(36).toUpperCase() + ' \u00b7 ' + new Date().toLocaleString() + '</div>';
  show.forEach(function(item, index){
    var cat = getDreamCategory(item.t + item.d);
    h += '<div style="margin-bottom:0.6rem;padding:0.8rem;background:linear-gradient(135deg,#FFFDF8,#FBEFDD);border:1px solid #E3C58A;border-radius:10px">';
    h += '<div style="display:flex;align-items:center;justify-content:space-between;gap:0.5rem;flex-wrap:wrap"><b style="color:#AF2020">' + (index+1) + '. ' + item.t + '</b><span style="font-size:0.7rem;color:#fff;background:#AF2020;padding:0.15rem 0.5rem;border-radius:4px">' + cat + '</span></div>';
    h += '<p style="font-size:0.85rem;color:#555;line-height:1.8;margin-top:0.4rem">' + item.d + '</p></div>';
  });
  
  h += '<div style="margin-top:0.8rem;padding:0.7rem;background:#FFFDF8;border:1px solid #E3C58A;border-radius:8px;color:#6B4B1F;font-size:0.82rem;line-height:1.8">收获提示：梦境是内心的提示，宜结合现实行动，保持开放心态，把提醒转化为具体计划。</div>';
  h += getHeartLine();
  h += '<button onclick="window.print()" style="padding:0.55rem 1.2rem;background:linear-gradient(135deg,#AF2020,#D4A030);color:#fff;border:none;border-radius:8px;cursor:pointer;margin-top:0.5rem">打印 / PDF</button>';
  h += '</div>';
  box.innerHTML = h;
}



(function(){
  var el = document.getElementById("dreamCount");
  if(el && typeof DREAM_DATA !== "undefined"){ el.textContent = DREAM_DATA.length.toLocaleString() + " \u6761"; }
})();


function appendHeartToReport(){
  var c = document.getElementById("rpContent");
  if(c && c.innerHTML.indexOf("\u5fc3\u5b89\u8bed") < 0){ c.innerHTML += getHeartLine(); }
}
(function(){
  var names = ["showReportContent", "showDreamReport"];
  for(var wi = 0; wi < names.length; wi++){
    var n = names[wi];
    if(typeof window[n] === "function"){
      var orig = window[n];
      window[n] = function(){
        var r = orig.apply(this, arguments);
        appendHeartToReport();
        return r;
      };
    }
  }
})();


function generateNames(){
  var surname = document.getElementById("nSurname").value.trim();
  if(!surname){ alert("请输入姓氏"); return; }
  var params = {
    surname: surname,
    gender: document.getElementById("nGender").value || "m",
    year: parseInt(document.getElementById("nYear").value) || 1990,
    month: parseInt(document.getElementById("nMonth").value) || 1,
    day: parseInt(document.getElementById("nDay").value) || 1,
    hour: parseInt(document.getElementById("nHour").value) || -1
  };
  try{ localStorage.setItem("name_draft", JSON.stringify(params)); }catch(err){}
  var paid = false;
  try{ paid = typeof isPaid === "function" ? isPaid() : (localStorage.getItem("js_paid") === "true"); }catch(err){}
  if(!paid){ showPaywall(); return; }
  renderNameReportFromParams(params);
}

var _EXTRA_DREAMS = [{keyword:'鼻毛',t:'梦见鼻毛',d:'鼻为肺之窍，又主审辨与财帛。鼻毛象征身体细节与防微杜渐：长出鼻毛提示关注呼吸道健康与自我形象；清理鼻毛代表整理细节、清除隐患；鼻毛杂乱提醒近期留意健康与财务细节。',src:'现代补充·取象比类'},{keyword:'汽车',t:'梦见汽车',d:'汽车象征古代车马、轿辇，主行动、道路与事业运。梦见开车平稳预示方向顺遂；方向盘失控表示近期选择需谨慎；汽车故障提示事业或出行受阻；车内乘客代表同路之人或贵人。',src:'现代补充·取象比类'},{keyword:'手机',t:'梦见手机',d:'手机如古代信使、飞鸽、驿站，主消息与联络。梦见手机响起预示有消息将至；手机丢失或没电，提示近期可能错过重要联系；换新手机代表新的沟通机会。',src:'现代补充·取象比类'},{keyword:'电脑',t:'梦见电脑',d:'电脑如古代书案、文书、机关，主工作与信息。梦见电脑顺畅预示事务推进；电脑故障或死机，提示工作细节需复查；电脑文件代表积累与成果。',src:'现代补充·取象比类'},{keyword:'电梯',t:'梦见电梯',d:'电梯象征阶梯与登高，主升迁与阶段变化。电梯上行预示地位或事业上升；下行代表阶段性回落；电梯故障提示等待时机。',src:'周易取象参考'},{keyword:'飞机',t:'梦见飞机',d:'飞机如大鹏腾云、驿传远行，主高远与快速进展。梦见飞机起飞预示新机会开启；飞行平稳代表志向可成；飞机延误提示计划需耐心。',src:'周易取象参考'},{keyword:'火车',t:'梦见火车',d:'火车如舟车行旅，主长途与按部就班。梦见火车准点预示计划顺利；赶不上火车，提示重要安排需提前准备。',src:'现代补充·取象比类'},{keyword:'快递',t:'梦见快递',d:'快递如信报、包裹，主远方消息与结果。梦见收到快递预示期待之事将有回音；快递丢失或破损，提示留意信息与承诺。',src:'现代补充·取象比类'},{keyword:'银行',t:'梦见银行',d:'银行如库房、仓廪，主储蓄与财运。梦见银行存款预示积累；取款代表支出或动用储备；银行排队提示财务事务需耐心处理。',src:'现代补充·取象比类'},{keyword:'方向盘',t:'梦见方向盘',d:'方向盘如古代执辔驾车，主掌控方向。方向盘顺手预示方向明确；方向盘失控提示近期需谨慎决策。',src:'现代补充·取象比类'},{keyword:'加油站',t:'梦见加油站',d:'加油站如古代驿站、补给，主补充能量与前进动力。加油顺利预示能量充足；加油站等待提示需缓冲与规划。',src:'现代补充·取象比类'}];
